import{_ as e,o as a,c as s,a2 as o}from"./chunks/framework.BbQrW5_t.js";const u=JSON.parse('{"title":"代码审计 · PHP 与 Python","description":"","frontmatter":{"title":"代码审计 · PHP 与 Python","date":"2026-09-03T00:00:00.000Z","tags":["网络安全","中级"]},"headers":[],"relativePath":"study/cyber-security/chapters/中级篇/06-代码审计-PHP与Python.md","filePath":"study/cyber-security/chapters/中级篇/06-代码审计-PHP与Python.md","lastUpdated":1788493831000}'),d={name:"study/cyber-security/chapters/中级篇/06-代码审计-PHP与Python.md"};function l(i,t,n,r,c,p){return a(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="_06-·-代码审计-php-与-python——弱类型与-危险的一句话" tabindex="-1">06 · 代码审计 PHP 与 Python——弱类型与&quot;危险的一句话&quot; <a class="header-anchor" href="#_06-·-代码审计-php-与-python——弱类型与-危险的一句话" aria-label="Permalink to &quot;06 · 代码审计 PHP 与 Python——弱类型与&quot;危险的一句话&quot;&quot;">​</a></h1><blockquote><p>PHP 统治存量 Web（审计市场最大）；Python 统治新工具链（你的主战场）。两章并一章，各给一张&quot;坑表&quot;+ 一套 Checklist。</p></blockquote><h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><ol><li>熟练运用 PHP 弱类型比较表识别绕过点</li><li>记全 PHP 危险函数家族（按类别）</li><li>说清 pickle 反序列化为什么&quot;天然就是 RCE&quot;</li><li>产出一套可复用的双语言审计 Checklist</li></ol><h2 id="📖-核心知识" tabindex="-1">📖 核心知识 <a class="header-anchor" href="#📖-核心知识" aria-label="Permalink to &quot;📖 核心知识&quot;">​</a></h2><h3 id="_6-1-php-弱类型坑表-的陷阱" tabindex="-1">6.1 PHP 弱类型坑表（== 的陷阱） <a class="header-anchor" href="#_6-1-php-弱类型坑表-的陷阱" aria-label="Permalink to &quot;6.1 PHP 弱类型坑表（== 的陷阱）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表达式</th><th>结果</th><th>利用场景</th></tr></thead><tbody><tr><td><code>0 == &quot;abc&quot;</code></td><td>true（历史版本）</td><td>数字参数传字符串绕过</td></tr><tr><td><code>&quot;1e3&quot; == &quot;1000&quot;</code></td><td>true</td><td>科学计数法绕数值校验</td></tr><tr><td><code>&quot;0e123&quot; == &quot;0e456&quot;</code></td><td>true</td><td><strong>科学计数法哈希碰撞</strong>（0e 开头=0）</td></tr><tr><td><code>null == false == 0</code></td><td>true</td><td>未初始化变量绕过</td></tr><tr><td><code>&quot;123abc&quot; == 123</code></td><td>true</td><td>截断转换绕过</td></tr></tbody></table><p>经典题：<code>if (md5($a) == md5($b) &amp;&amp; $a != $b)</code> → 找两个 <code>0e...</code> 开头的 MD5（全部解析为 0）即过。</p><h3 id="_6-2-php-危险函数家族" tabindex="-1">6.2 PHP 危险函数家族 <a class="header-anchor" href="#_6-2-php-危险函数家族" aria-label="Permalink to &quot;6.2 PHP 危险函数家族&quot;">​</a></h3><table tabindex="0"><thead><tr><th>家族</th><th>函数</th><th>危害</th></tr></thead><tbody><tr><td>命令执行</td><td>system/exec/shell_exec/passthru/\`\`/popen</td><td>RCE</td></tr><tr><td>代码执行</td><td>eval/assert/create_function/preg_replace(/e)</td><td>RCE</td></tr><tr><td>文件操作</td><td>include/require/file_get_contents/fopen</td><td>LFI/RFI/读文件</td></tr><tr><td>上传</td><td>move_uploaded_file+扩展名校验缺陷</td><td>webshell</td></tr><tr><td>反序列化</td><td>unserialize（__destruct/__wakeup 魔术方法链）</td><td>依赖库 gadget</td></tr><tr><td>SSRF</td><td>curl_exec/file_get_contents(http)</td><td>内网</td></tr></tbody></table><p>审计口诀：<strong>grep 危险函数 → 回溯参数来源 → 判断过滤强度</strong>（与 Java 审计同构）。</p><h3 id="_6-3-php-审计实战框架" tabindex="-1">6.3 PHP 审计实战框架 <a class="header-anchor" href="#_6-3-php-审计实战框架" aria-label="Permalink to &quot;6.3 PHP 审计实战框架&quot;">​</a></h3><ol><li>路由/入口梳理（框架类：<code>routes.php</code> 或注解）</li><li>全局过滤点识别（<code>addslashes</code>/框架 GPC/自定义 filter）——<strong>绕过点=过滤薄弱的边界</strong></li><li>危险函数 grep → 逐个回溯</li><li>特别关注：<code>$$var</code>（可变变量覆盖）、<code>extract()</code>（变量注入）、<code>unserialize</code> 入口</li></ol><h3 id="_6-4-python-特有面" tabindex="-1">6.4 Python 特有面 <a class="header-anchor" href="#_6-4-python-特有面" aria-label="Permalink to &quot;6.4 Python 特有面&quot;">​</a></h3><p><strong>SSTI</strong>（中级篇 03 已详解）与 <strong>pickle 反序列化</strong>：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pickle</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pickle.loads(user_bytes)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ← 天然 RCE：pickle 协议支持 REDUCE 操作码</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#攻击者构造 __reduce__ 返回 (os.system, (&#39;命令&#39;,))——恢复时直接执行</span></span></code></pre></div><p>为什么 pickle 比 Java 反序列化&quot;更直白&quot;：pickle 协议<strong>设计上就允许序列化&quot;如何构造对象&quot;的指令</strong>，<code>__reduce__</code> 就是&quot;对象 + 调用参数&quot;。防御：<strong>永远不要 loads 不可信数据</strong>，换 JSON。</p><p><strong>Flask 调试 PIN</strong>：debug 模式下 Werkzeug 控制台 PIN 由机器特征（MAC/用户名/machine-id 等）计算——泄露任意文件读即可算出 PIN，debug=生产事故。</p><p><strong>eval/exec</strong>：任何&quot;把字符串当代码&quot;的入口都是 RCE；审计 grep <code>eval(|exec(|__import__</code>。</p><h3 id="_6-5-双语言审计-checklist-模板" tabindex="-1">6.5 双语言审计 Checklist（模板） <a class="header-anchor" href="#_6-5-双语言审计-checklist-模板" aria-label="Permalink to &quot;6.5 双语言审计 Checklist（模板）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ ] 入口清单完整（路由/CLI/cron/消息消费者）</span></span>
<span class="line"><span>[ ] 输入点标注（参数/Cookie/头/文件名/JSON 字段）</span></span>
<span class="line"><span>[ ] 过滤边界图（全局过滤/局部过滤/无过滤）</span></span>
<span class="line"><span>[ ] 危险汇点 grep 清单（本语言家族表）</span></span>
<span class="line"><span>[ ] 逐汇点数据流回溯（source→sink 路径图）</span></span>
<span class="line"><span>[ ] 认证/授权检查（越权测试点）</span></span>
<span class="line"><span>[ ] 依赖版本 vs 已知 CVE（pip list/mvn tree 对照）</span></span>
<span class="line"><span>[ ] 结论：PoC+数据流图+修复建议</span></span></code></pre></div><h2 id="🔬-动手实操" tabindex="-1">🔬 动手实操 <a class="header-anchor" href="#🔬-动手实操" aria-label="Permalink to &quot;🔬 动手实操&quot;">​</a></h2><ol><li>本地复现 <code>0e</code> MD5 绕过（写 10 行 PHP 验证脚本）</li><li>用 Docker 跑一个小型 PHP 开源系统（如永恒蓝类靶场），按 6.5 清单做一次完整审计</li><li>Python 侧：写一个 <code>pickle.loads</code> 演示（自建对象 + <code>__reduce__</code>），在本地理解&quot;为什么不能 loads 不可信数据&quot;</li></ol><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ol><li>PHP 8 后部分弱类型行为改变（<code>0==&quot;abc&quot;</code> 为 false）——<strong>先确认目标版本再下结论</strong></li><li>只盯 eval/system——include/unserialize 才是存量系统的主流入口</li><li>Python 觉得&quot;类型安全&quot;就没审计价值——pickle/eval/SSTI 全是 RCE 级</li><li>框架审计跳过框架本身的已知漏洞（ThinkPHP/Flask 历史洞）</li><li>Checklist 一次不用——审计的工程化就靠它</li></ol><h2 id="✅-自测题" tabindex="-1">✅ 自测题 <a class="header-anchor" href="#✅-自测题" aria-label="Permalink to &quot;✅ 自测题&quot;">​</a></h2><details><summary>1. &quot;0e123&quot; == &quot;0e456&quot; 为什么为 true？</summary><p>PHP == 比较时两者都符合科学计数法格式，被解析为浮点 0<em>10^123 == 0</em>10^456 = 0 == 0。用于绕&quot;两个不同字符串但 MD5 相等&quot;类校验（用 0e 开头的 MD5 碰撞串）。</p></details><details><summary>2. PHP 反序列化的攻击入口为什么是魔术方法？</summary><p>unserialize 恢复对象时会自动触发 __wakeup/__destruct 等生命周期方法；gadget 链借这些&quot;自动调用点&quot;启动，后续环靠类内自定义逻辑衔接。</p></details><details><summary>3. pickle 为什么比 JSON 危险？</summary><p>JSON 只表达数据；pickle 协议可表达&quot;构造对象的指令&quot;（REDUCE 操作码），loads 时执行任意可调用对象——数据与代码未分离。</p></details><details><summary>4. Flask debug 模式的生产风险链？</summary><p>任意文件读（LFI/SSRF 组合）→ 读取 machine-id/MAC/用户名 → 计算 Werkzeug PIN → 访问 /console 得到交互式 Python 控制台 → RCE。生产必须关 debug。</p></details><details><summary>5. 审计中&quot;过滤边界图&quot;指什么？</summary><p>标出全局过滤（GPC 转义/WAF/框架中间件）作用与失效条件，找&quot;局部漏网&quot;——漏洞几乎都在过滤覆盖的接缝处。</p></details><h2 id="🔗-对应周任务与资源" tabindex="-1">🔗 对应周任务与资源 <a class="header-anchor" href="#🔗-对应周任务与资源" aria-label="Permalink to &quot;🔗 对应周任务与资源&quot;">​</a></h2><ul><li><strong>W73-W76</strong>；资源：《代码审计：企业级Web代码安全架构》、PHP 官方类型比较表、Pickle 文档&quot;安全警告&quot;节</li></ul>`,33)])])}const P=e(d,[["render",l]]);export{u as __pageData,P as default};
